    "import matplotlib.pyplot as plt\n",
    "labels=['Bila ovebooking', 'Na overbooking']\n",
    "pesa=[45000, 47250]\n",
    "\n",
    "plt.figure(figsize=(6,4))\n",
    "plt.bar(labels, pesa, color=['gray','gold'])\n",
    "plt.title('Emirates DXB-JRO - Overbooking profit')\n",
    "plt.ylabel('Pesa ($)')\n",
    "plt.text(1,47250 +200, f\"+${profit_extra}\", ha='center', fontweight='bold')\n",
    "plt.show()\n",
    "print(\"Hii graph inaingia kwenye presentation ya kazi Dubai!\")         "
